{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Trazodone, a high-transfer analogue sharing an aryl chloride and basic amine, showed 65% absolute oral bioavailability in fed volunteers, directly supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Isoniazid in fed patients showed 78% oral bioavailability, supporting high systemic availability in the fed state despite structural differences.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, an amide-containing basic drug, had 75% absolute oral bioavailability after oral dosing, supporting high F for the query's amide/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Molsidomine, despite significant first-pass metabolism, had 44±15% absolute oral bioavailability, still well above the 20% threshold and supporting a high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "E4031, a basic amine drug, showed 92.2% absolute oral bioavailability, providing additional high-transfer evidence that this compound class is well absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20% (44–93%), including fed-state measurements. The query's amide/morpholine structure is consistent with good absorption and only moderate first-pass metabolism, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself.",
    "No query-specific fed-state pharmacokinetic study is available; fed-state support comes from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

